GIKAI.cases.push(...[
{"title":"手話言語条例は誰が案を練り、誰が提出したか","place":"さいたま市","actors":["西山幸代","稲川智美","堤日出喜","大貫田鶴子","吉村豪介","佐藤真実","関ひろみ","土橋勇司","都築龍太","久保美樹","高柳俊哉","江原大輔","手話言語条例検討プロジェクトチーム"],"topic":"福祉・条例","steps":[{"date":"2024-10-18","actor":"手話言語条例検討プロジェクトチーム","stage":"検討開始","detail":"議員12人のチームが初会合を開いた。会長は西山幸代、会長職務代理者は稲川智美。全委員と各回の資料が公開されている。","url":"https://www.city.saitama.lg.jp/gikai/005/shuwagenngo/p117352.html","sourceTitle":"さいたま市議会「手話言語条例検討プロジェクトチーム」"},{"date":"2025-01-31","actor":"手話言語条例検討プロジェクトチーム、聴覚障害者協会、手話通訳問題研究会","stage":"意見聴取","detail":"12人の委員が当事者団体と通訳関係団体から意見を聞いた。通訳者の定義、地域で使う手話、災害時の支援について具体的に協議した。","url":"https://www.city.saitama.lg.jp/gikai/005/shuwagenngo/p117352_d/fil/r070131-6.pdf","sourceTitle":"第4回会議の開催結果"},{"date":"2025-05-09","actor":"手話言語条例検討プロジェクトチーム","stage":"条例案の決定","detail":"市民意見への対応を審議し、素案に修正を加えた。出席した委員11人の意見が一致し、チームの案を決定した。","url":"https://www.city.saitama.lg.jp/gikai/005/shuwagenngo/p117352_d/fil/r070509-4.pdf","sourceTitle":"第8回会議の開催結果"},{"date":"2025-06-11","actor":"西山幸代、稲川智美ほか10人","stage":"議員提案","detail":"議案書は提出者を西山幸代・稲川智美とし、ほかの委員10人を賛成者として一人ずつ記載している。","url":"https://www.city.saitama.lg.jp/006/014/008/003/014/003/p121912_d/fil/zyoureigian.pdf","sourceTitle":"議員提出議案第2号・署名欄"},{"date":"2025-06-11","actor":"さいたま市議会","stage":"本会議で議決","detail":"市議会が条例を議決。手話の理解・普及について市の責務と市民・事業者の役割を定めた。","url":"https://www.city.saitama.lg.jp/006/014/008/003/014/003/p121912.html","sourceTitle":"さいたま市「さいたま市手話言語条例が議決されました」"}],"note":"案の検討は12人の共同作業。議案書の「賛成者」は提出段階の役割で、本会議で投票した全議員の一覧とは区別される。"},
{"title":"高等専修学校の入学金・施設費をめぐり、答弁を問い直す","place":"埼玉県","actors":["金野桃子"],"topic":"教育・家計","steps":[{"date":"2026-10-02","actor":"金野桃子","stage":"聞き取りを踏まえた一般質問","detail":"私立専修学校の教員に会派で聞いた内容を報告。保護者の負担を軽くする補助について、高等専修学校の入学金と施設費が対象外である理由を問うた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/e/07.html","sourceTitle":"埼玉県議会「令和8年9月定例会・金野桃子議員の一般質問と答弁」"},{"date":"2026-10-02","actor":"金野桃子","stage":"再質問・再々質問","detail":"知事の説明が学校の運営費補助を扱っていたため、世帯向けの入学金・施設費への補助について聞いていると確認した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/e/07.html","sourceTitle":"埼玉県議会「令和8年9月定例会・金野桃子議員の一般質問と答弁」"},{"date":"2026-10-02","actor":"大野元裕知事","stage":"答弁の訂正","detail":"直前の答弁が学校運営費に関するものだったと訂正。入学金・施設費への補助は財源も含めて検討すると答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/e/07.html","sourceTitle":"埼玉県議会「令和8年9月定例会・金野桃子議員の一般質問と答弁」"}],"note":"再々質問により、二つの補助制度の違いが答弁上明確になった。この日の結論は財源を含む検討。"},
{"title":"子どもの高次脳機能障害をめぐり、県外病院を調べて再び問う","place":"埼玉県","actors":["木村勇夫","小川寿士","田並尚明"],"topic":"医療・障害福祉","steps":[{"date":"2026-02-26","actor":"木村勇夫","stage":"代表質問","detail":"小児の回復期リハビリのため県外に通う家族の負担を挙げ、県内での専門的な医療・支援体制を知事に問うた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0802/4/b/0501.html","sourceTitle":"埼玉県議会「令和8年2月定例会・木村勇夫議員の代表質問と答弁」"},{"date":"2026-08-25","actor":"小川寿士、田並尚明","stage":"現地調査","detail":"神奈川リハビリテーション病院を訪ね、医師やソーシャルワーカーに聞き取ったと、小川議員が10月の本会議で報告した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/b/0201.html","sourceTitle":"埼玉県議会「令和8年9月定例会・小川寿士議員の一般質問と答弁」"},{"date":"2026-10-01","actor":"小川寿士、県福祉部長","stage":"調査後の質問・答弁","detail":"視察先と県内の対応の差を問うた。福祉部長は県内48の医療機関が18歳未満を診断・支援する一方、小児に特化した機関がなく生活環境の調整にも課題があると答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/b/0201.html","sourceTitle":"埼玉県議会「令和8年9月定例会・小川寿士議員の一般質問と答弁」"},{"date":"2026-10-01","actor":"大野元裕知事","stage":"実態調査の方針","detail":"医療・福祉の必要を調べ、専門家と分析したうえで小児のリハビリ提供体制を中長期的に検討すると答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/b/0202.html","sourceTitle":"埼玉県議会「令和8年9月定例会・小川寿士議員の一般質問と答弁」"}],"note":"代表質問、現地での聞き取り、調査後の質問はそれぞれの議員の活動。県が示したのは整備を検討する手順。"},
{"title":"かすかべ夢の森公園の遊具が使えるまで","place":"埼玉県","actors":["権守幸男"],"topic":"公園・子育て","steps":[{"date":"2023-06-23","actor":"権守幸男","stage":"住民の声を受けた提案","detail":"県営公園で子どもが使う遊具を望む来園者の声を紹介し、遊具の設置など四つの活用策を県に提案した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0506/4/c0830.html","sourceTitle":"埼玉県議会「令和5年6月定例会・権守幸男議員の一般質問と答弁」"},{"date":"2024-10-01","actor":"権守幸男、県都市整備部長","stage":"継続質問・答弁","detail":"前年の答弁後の進捗を確認。県は近県の事例や地元協議会の意見を調べ、年度後半に遊具を設計する方針を説明した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0609/r0609-4/c/0750.html","sourceTitle":"埼玉県議会「令和6年9月定例会・権守幸男議員の一般質問と答弁」"},{"date":"2026-10-01","actor":"権守幸男、県都市整備部長","stage":"利用者の意見を確認","detail":"来園者の要望をどう反映したかを質問。県は利用者らに四つの候補を示して希望を募り、最多の案を選んだと答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/c/1003.html","sourceTitle":"埼玉県議会「令和8年9月定例会・権守幸男議員の一般質問と答弁」"},{"date":"2026-10-23","actor":"公園管理者","stage":"利用開始","detail":"活動広場の遊具を正午から利用できると公園が発表した。","url":"https://kasukabe-yumenomori.jp/%E9%81%8A%E5%85%B7-%E5%88%A9%E7%94%A8%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%88%E3%81%97%E3%81%BE%E3%81%99%EF%BC%81%EF%BC%88%E6%B4%BB%E5%8B%95%E5%BA%83%E5%A0%B4%EF%BC%89/","sourceTitle":"豊春会 かすかべ夢の森公園「遊具 利用スタートします！（活動広場）」"}],"note":"議会資料では権守議員の継続した働きかけ、県の調査・整備、利用者の選定への参加がそれぞれ確認できる。"},
{"title":"金属スクラップなどの屋外保管に許可制度を設ける","place":"埼玉県","actors":["中屋敷慎一","埼玉県議会自由民主党議員団"],"topic":"環境・条例","steps":[{"date":"2024-06-21","actor":"中屋敷慎一","stage":"会派案を説明","detail":"議会運営委員会で、火災や敷地外への崩落などの課題と、既存の法令では規制が届かない事例を説明。会派の条例案を各会派に持ち帰って検討するよう求めた。","url":"https://www.pref.saitama.lg.jp/documents/259141/giun-kaikaityu.pdf","sourceTitle":"埼玉県議会・令和6年6月定例会 議会運営委員会の概要（6月21日の発言）"},{"date":"2024-07-05","actor":"埼玉県議会","stage":"議決","detail":"特定再生資源屋外保管業を規制する議員提案条例を議決した。7月9日に公布された。","url":"https://www.pref.saitama.lg.jp/e1601/giinteianjourei.html","sourceTitle":"埼玉県議会「議員提案政策条例」第43項"},{"date":"2025-01-01","actor":"埼玉県","stage":"制度の施行","detail":"対象となる屋外保管業に知事の許可が必要になった。県は既存業者の届出手続も設けた。","url":"https://www.pref.saitama.lg.jp/a0506/saiseisigen/20240712.html","sourceTitle":"埼玉県「特定再生資源屋外保管業の規制に関する条例」"}],"note":"中屋敷委員について確認できるのは会派案の説明。条例を議決したのは県議会で、許可と監督を担うのは県。"},
{"title":"被災地の運営を調べ、避難情報と福祉避難所の改善を提言","place":"新座市","actors":["新座市議会総務常任委員会"],"topic":"防災・避難","steps":[{"date":"2024-07-24","actor":"総務常任委員会","stage":"先行事例の調査","detail":"山形市を訪問し、住民による自主防災組織をどう支援しているか調査した。","url":"https://www.city.niiza.lg.jp/uploaded/attachment/69390.pdf","sourceTitle":"新座市議会総務常任委員会・政策提言書「災害に強いまちづくり」"},{"date":"2025-05-12","actor":"総務常任委員会","stage":"被災地の調査","detail":"熊本県人吉市で豪雨災害の検証について聞き取り、翌13日には県防災センターと益城町で災害対応と条例を調べた。","url":"https://www.city.niiza.lg.jp/uploaded/attachment/69390.pdf","sourceTitle":"新座市議会総務常任委員会・政策提言書「災害に強いまちづくり」"},{"date":"2025-12-16","actor":"新座市議会、総務常任委員会","stage":"市長への提言","detail":"無線やLINEなどを組み合わせる情報伝達、福祉避難所に直接避難できる仕組みの検討などを提言。市議会は常任委員会の研究を基に市長に提出した。","url":"https://www.city.niiza.lg.jp/soshiki/52/seisakukenkyuu.html","sourceTitle":"新座市議会「常任委員会における政策研究・政策提言」"}],"note":"提言書には視察先、会議日、各提案が記録されている。提言の作成主体は委員会、提出主体は市議会。"},
{"title":"学童保育と子育て支援の提言を委員の意見で書き直す","place":"所沢市","actors":["川辺浩直","中井めぐみ","斎藤由紀","大庭祥照","赤川洋二","所沢市議会健康福祉常任委員会"],"topic":"学童・子育て","steps":[{"date":"2024-10-10","actor":"健康福祉常任委員会","stage":"提言案の検討","detail":"正副委員長が提言案を示し、委員の意見を集めた。経過は翌月の会議記録冒頭に記されている。","url":"https://www.city.tokorozawa.saitama.jp/shigikai/tokubetuiinkaijyouhou/jyonininkai/kenko.files/R6.11.15_kennkouhukushi.pdf","sourceTitle":"所沢市議会・健康福祉常任委員会会議記録（令和6年11月15日）"},{"date":"2024-11-15","actor":"川辺浩直、中井めぐみ、斎藤由紀、大庭祥照、赤川洋二","stage":"提言案の修正","detail":"川辺委員長の進行の下、中井委員は学童を子どもの生活の場と位置付ける表現を提案。斎藤委員の用語の提案について大庭・赤川委員も意見を述べ、委員会で修正した。","url":"https://www.city.tokorozawa.saitama.jp/shigikai/tokubetuiinkaijyouhou/jyonininkai/kenko.files/R6.11.15_kennkouhukushi.pdf","sourceTitle":"所沢市議会・健康福祉常任委員会会議記録（令和6年11月15日）"},{"date":"2025-02-15","actor":"健康福祉常任委員会","stage":"提出を議会報で公表","detail":"市議会だよりは、学童の定員拡大、保育士の労働環境の改善など6項目の提言をこども未来部に手渡したと報告した。","url":"https://www.city.tokorozawa.saitama.jp/shigikai/dayori/shigikaidayori-r6.files/213-all.pdf","sourceTitle":"ところざわ市議会だより・第213号"}],"note":"議員ごとの修正意見は会議記録に、委員会の提言は議会報に残っている。最後の日付は議会報の発行日。"},
{"title":"体育館の空調整備を町議会の要望と町の予算でたどる","place":"寄居町","actors":["寄居町議会"],"topic":"防災・公共施設","steps":[{"date":"2025-10-07","actor":"寄居町議会","stage":"提言の公表","detail":"総合体育館・アタゴ記念館の空調を優先し、小中学校の体育館にも整備するよう求める提言を町に提出したと公表した。","url":"https://www.town.yorii.saitama.jp/site/gikai/teigenr-8.html","sourceTitle":"寄居町議会「令和8年度に向けた提言書」"},{"date":"2026-04","actor":"寄居町","stage":"実施設計の予算","detail":"4月の町広報で、総合体育館・アタゴ記念館の空調の実施設計に1,334万円、中学校体育館の分に3,061万円を計上したと説明した。","url":"https://www.town.yorii.saitama.jp/uploaded/attachment/27325.pdf","sourceTitle":"広報よりい・令和8年4月号「令和8年度 寄居町の施策と予算」"}],"note":"総合体育館の基本設計は令和6年度に町が実施済み。町議会の役割は整備の優先順位を示したこと。予算の対象は実施設計。"},
{"title":"救急搬送の受け入れ先が決まるまでの指標を検証","place":"埼玉県","actors":["橋本健人"],"topic":"救急医療","steps":[{"date":"2025-08","actor":"埼玉県","stage":"事業開始","detail":"75歳以上の重症救急患者の受け入れを支援する事業を開始。開始時点で47の医療機関が参加したと県が翌年の議会で報告した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/d/0202.html","sourceTitle":"埼玉県議会「令和8年6月定例会・橋本健人議員の一般質問と答弁」"},{"date":"2026-06-22","actor":"橋本健人","stage":"一般質問・再質問","detail":"重症患者の搬送先への照会が4回以上に及ぶ割合を取り上げ、県の対策の期限と具体策、統計上の改善が住民の安心にどうつながるかを尋ねた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/d/0202.html","sourceTitle":"埼玉県議会「令和8年6月定例会・橋本健人議員の一般質問と答弁」"},{"date":"2026-06-22","actor":"県保健医療部長","stage":"実績を説明","detail":"県によれば、2026年3月までの75歳以上の重症以上の患者で照会が4回以上となった割合は前年同期間より4.3ポイント低下。答弁時点の参加機関は99だった。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/d/0202.html","sourceTitle":"埼玉県議会「令和8年6月定例会・橋本健人議員の一般質問と答弁」"}],"note":"事業開始は今回の質問より前。確認できる議員の働きは、既存事業の効果と次の対策を具体的な指標でただしたこと。"},
{"title":"困難を抱える女性の支援計画を、市町村にどう広げるか","place":"埼玉県","actors":["城下のり子"],"topic":"福祉・市町村支援","steps":[{"date":"2026-06-23","actor":"城下のり子","stage":"進捗の検証","detail":"困難な問題を抱える女性への支援について、計画を作った市町村と未策定の市町村との隔たりを指摘し、県の支援を求めた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/h/0308.html","sourceTitle":"埼玉県議会「令和8年6月定例会・城下のり子議員の一般質問と答弁」"},{"date":"2026-06-23","actor":"大野元裕知事","stage":"策定状況の答弁","detail":"策定した自治体は令和7年度の13市町から令和8年度は27市町になり、別に16市町が検討中と答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/h/0308.html","sourceTitle":"埼玉県議会「令和8年6月定例会・城下のり子議員の一般質問と答弁」"},{"date":"2026-06-23","actor":"城下のり子、大野元裕知事","stage":"支援方法を再質問","detail":"城下議員が助言の具体的な内容を確認。知事は他自治体の事例や策定に使える支援制度を紹介すると説明した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0806/4/h/0308.html","sourceTitle":"埼玉県議会「令和8年6月定例会・城下のり子議員の一般質問と答弁」"}],"note":"27市町、16市町は答弁時点の状況。各市町村が策定主体で、県はその作業を支援する。"},
{"title":"無料低額宿泊所の改善指導が現場に届いたかを問う","place":"埼玉県","actors":["山田裕子"],"topic":"生活困窮・行政監視","steps":[{"date":"2026-10-02","actor":"山田裕子","stage":"監督方法の質問","detail":"事業者が改善報告書を出した後、入居者の生活環境の変化をどう確かめるのかを質問。必要時の再検査や入居者への聞き取りを求めた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/f/0202.html","sourceTitle":"埼玉県議会「令和8年9月定例会・山田裕子議員の一般質問と答弁」"},{"date":"2026-10-02","actor":"山田裕子","stage":"調査結果による再質問","detail":"県に実態調査を依頼したところ居室に冷房がないと答えた施設があったと報告し、猛暑に備えた具体的な対応を再度確認した。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/f/0202.html","sourceTitle":"埼玉県議会「令和8年9月定例会・山田裕子議員の一般質問と答弁」"},{"date":"2026-10-02","actor":"県福祉部長","stage":"指導・継続確認の答弁","detail":"居室に冷房がない場合は設置するか、扇風機と冷房のある空間を確保するよう指導し、対応を継続確認すると答えた。","url":"https://www.pref.saitama.lg.jp/e1601/gikai-gaiyou/r0809/4/f/0202.html","sourceTitle":"埼玉県議会「令和8年9月定例会・山田裕子議員の一般質問と答弁」"}],"note":"資料で確認できるのは山田議員の調査依頼・質問と県の指導方針。施設での設置完了を示す資料とは区別する。"},
{"title":"いったん提出した避難所の提言を、被災地の経験で点検","place":"戸田市","actors":["戸田市議会総務常任委員会"],"topic":"防災・避難","steps":[{"date":"2024-01","actor":"総務常任委員会","stage":"住民との懇談を踏まえた提言","detail":"自主防災会との懇談と自治体視察を踏まえ、避難所運営マニュアルや防災倉庫の鍵の共有、トイレの確保などを市に提言した。","url":"https://www01.sites.gijiroku.com/gikai/toda-f9fzqijq2awo0kaj/DownLoadTempuFile?dataId=0000047514&fileId=b28277497dd64a429d71ca11d51cdd4b&fileName=Sr2B220_reiwa5seika.pdf","sourceTitle":"令和5年戸田市議会年間活動成果・総務常任委員会"},{"date":"2024-12","actor":"総務常任委員会","stage":"過去の提言の再検証","detail":"能登半島地震の避難所運営を調べ、長期にわたり避難所を運営した自治体を視察。過去の提言も点検し、備蓄の保管・在庫、避難所外の人の把握、暑さ寒さへの対策を盛り込んだ提言を提出した。","url":"https://www01.sites.gijiroku.com/gikai/toda-f9fzqijq2awo0kaj/DownLoadTempuFile?dataId=0000047513&fileId=e45ab770e2e64bdcac05035028fef036&fileName=Sr2B243_R612katsudouseika.pdf","sourceTitle":"令和6年戸田市議会年間活動成果・総務常任委員会"}],"note":"２年度の委員会活動報告が、住民への聞き取りと過去の提言を検証し直した経過を記録している。"},
{"title":"不登校の子どもの居場所と学び方を調べる","place":"飯能市","actors":["飯能市議会総務教育委員会"],"topic":"教育・居場所","steps":[{"date":"2024-04-01","actor":"飯能市議会の常任委員会","stage":"調査の開始","detail":"市議会の記録によると、常任委員会がそれぞれの担当分野の事務を調査する取り組みを始めた。","url":"https://www.city.hanno.lg.jp/shiseijoho/shigikai/shigikainoaramashi/3454.html","sourceTitle":"飯能市議会「議会改革の取り組み」"},{"date":"2025-02-04","actor":"総務教育委員会などの常任委員会","stage":"市長への政策提言","detail":"総務教育委員会は学びを保障する方法を調べ、学校・家庭・地域による支援、オンライン授業の拡充、義務教育終了後の支援などを提言した。各常任委員会の提言書を市長に提出した。","url":"https://www.city.hanno.lg.jp/shiseijoho/shigikai/shigikainoaramashi/3454.html","sourceTitle":"飯能市議会「議会改革の取り組み」"},{"date":"2025-05-01","actor":"飯能市議会","stage":"提言内容の公表","detail":"市議会だより175号15ページに提言の内容を掲載。生活福祉委員会と経済建設委員会による別テーマの提案も同じページで確認できる。","url":"https://www.city.hanno.lg.jp/material/files/group/45/gikaidayori175.pdf#page=15","sourceTitle":"もっと はんのう市議会・第175号15頁"}],"note":"学校への要望は、調査した委員会としての提案。資料には市長への提出日と提言内容がそれぞれ記録されている。"},
{"title":"決算審査で指摘した路線バスの課題を、次年度の予算案で追う","place":"さいたま市","actors":["さいたま市議会決算特別委員会"],"topic":"交通・予算監視","steps":[{"date":"2025-10","actor":"決算特別委員会・さいたま市議会","stage":"決算審査後の提言","detail":"前年度の各会計決算を審査し、次年度の予算に向けた改善点を13項目にまとめて市長に提出。このうち交通分野では路線バスへの支援と移動手段の確保を求めた。","url":"https://www.city.saitama.lg.jp/gikai/005/kouhou/001/p032519_d/fil/105p1-12.pdf","sourceTitle":"市議会だよりさいたま第105号・令和7年9月定例会"},{"date":"2026-01-27","actor":"決算特別委員会","stage":"提言の追跡","detail":"各会計決算の審査を踏まえた令和8年度の予算編成への提言書を、再び委員会の報告事項として扱った。","url":"https://www.city.saitama.lg.jp/gikai/002/003/006/p122889.html","sourceTitle":"さいたま市議会・決算特別委員会活動状況"},{"date":"2026-05-01","actor":"さいたま市議会","stage":"予算案との照合を公表","detail":"市議会だよりで、バス事業者への補助やコミュニティバスの改善支援、AIデマンド交通・自動運転バスの実証実験を提言への対応として紹介した。","url":"https://www.city.saitama.lg.jp/gikai/005/kouhou/001/p032519_d/fil/107p1-12.pdf#page=2","sourceTitle":"市議会だよりさいたま第107号2・3頁"}],"note":"予算案と要望のつながりは議会報が説明している。そこに示された事業費は関連費用を含み、提言で増額された金額を表すものではない。"},
{"title":"投票所に行きにくい人の移動を翌年度予算の論点にする","place":"寄居町","actors":["寄居町議会"],"topic":"選挙・移動支援","steps":[{"date":"2026-11-02","actor":"寄居町議会","stage":"提出を公表","detail":"令和9年度の予算に向けて町に提言書を提出したと公表した。投票環境の整備は、文書が取り上げた4項目の一つ。","url":"https://www.town.yorii.saitama.jp/site/gikai/teigenr-9.html","sourceTitle":"寄居町議会「令和9年度に向けた提言書」"},{"date":"2026-11-02","actor":"寄居町議会","stage":"要望内容の公表","detail":"投票所の段差への対策に加え、移動投票や電子投票について、費用、仕組み、運用上の課題を調べるよう町に求めた。","url":"https://www.town.yorii.saitama.jp/uploaded/attachment/28410.pdf","sourceTitle":"寄居町議会・令和9年度予算に向けた提言書（1頁）"}],"note":"日付は提言書の公表日。移動投票・電子投票についての記載は調査・検討の要望。"},
{"title":"玉ノ岡中学校北入口で、大型車規制と注意看板をどう判断したか","place":"嵐山町","actors":["畠山美幸","嵐山町長","まちづくり整備課長"],"topic":"通学路・交通安全","steps":[{"date":"2026-09","actor":"畠山美幸","stage":"一般質問","detail":"通学路でもある町道で下水道の緊急工事があったことを受け、工事費、大型車の規制、工業団地周辺の道路の強度を質問した。","url":"https://www.town.ranzan.saitama.jp/cmsfiles/contents/0000008/8030/204gikaidayori.pdf#page=6","sourceTitle":"嵐山町議会だより「らんざん」第204号 6頁"},{"date":"2026-09","actor":"地域支援課長、まちづくり整備課長、嵐山町長","stage":"答弁","detail":"町は工事と車両通行の因果関係を認めず、交通規制の導入は考えていないと答えた。関係企業への運行ルート分散の働きかけと、注意看板の協議に言及した。","url":"https://www.town.ranzan.saitama.jp/cmsfiles/contents/0000008/8030/204gikaidayori.pdf#page=6","sourceTitle":"嵐山町議会だより「らんざん」第204号 6頁"},{"date":"2026-10-16","actor":"嵐山町議会","stage":"設置後の写真","detail":"議会だよりが、同じ交差点に新たに設置された看板の10月16日付写真を掲載した。","url":"https://www.town.ranzan.saitama.jp/cmsfiles/contents/0000008/8030/204gikaidayori.pdf#page=6","sourceTitle":"嵐山町議会だより「らんざん」第204号 6頁"}],"note":"10月16日は写真の日付。交通規制を導入したという記録ではなく、設置主体や議員個人の寄与の大きさは資料から定められない。"},
{"title":"核兵器禁止条約について国への意見書を提出した議員と議決","place":"吉見町","actors":["杉田しのぶ","福田妙子","福井学","吉見町議会"],"topic":"議員提出議案・平和政策","steps":[{"date":"2026-09","actor":"杉田しのぶ（提出者）、福田妙子・福井学（賛成者）","stage":"議員発議","detail":"条約の再検討会議へのオブザーバー参加と、条約への署名・批准を国に求める意見書案を提出した。","url":"https://www.town.yoshimi.saitama.jp/material/files/group/3/gikai14.pdf#page=7","sourceTitle":"吉見町議会「よしみぎかい」第14号 7頁"},{"date":"2026-09","actor":"吉見町議会","stage":"質疑・討論","detail":"国際情勢や日米安全保障条約との関係を理由とする慎重論と、平和都市宣言を踏まえた行動を求める賛成論が記録された。","url":"https://www.town.yoshimi.saitama.jp/material/files/group/3/gikai14.pdf#page=7","sourceTitle":"吉見町議会「よしみぎかい」第14号 7頁"},{"date":"2026-09","actor":"吉見町議会","stage":"本会議で議決","detail":"賛成7、反対5、棄権1で可決。議案別の公式審議結果にも発議第4号の原案可決が掲載されている。","url":"https://www.town.yoshimi.saitama.jp/material/files/group/14/shingikekka809.pdf","sourceTitle":"吉見町議会「審議結果（令和8年9月議会定例会）」"}],"note":"署名・批准を求める意見書についての議決。町議会は提出者と議案提出時の賛成者を区別して公表している。"},
{"title":"中学校の部活動の暑さ対策を、屋内と校庭で続けて問う","place":"神川町","actors":["福島康弘","柴崎愛子","神川町議会","神川町"],"topic":"学校・熱中症対策","steps":[{"date":"2026-01-23","stage":"体育館の空調・非常用発電機工事の落札","actor":"神川町","detail":"神川中学校体育館の空調設備と非常用発電機の設置工事の入札で、長沼設備工業が税込1億1,550万円で落札した。入札結果表の工期は契約締結日から10月31日まで。","url":"https://www.town.kamikawa.saitama.jp/material/files/group/3/03_20260123_koji.pdf","sourceTitle":"神川町 １月23日の入札結果表"},{"date":"2026-03-18","stage":"落札後の審議で設備費と非常用発電機を質疑","actor":"福島康弘","detail":"契約額の内訳、発電機の稼働日数、燃料交換の頻度を尋ねた。町は、空調工事が概算４割、受変電設備の増設と非常用発電機工事が概算６割と説明した。","url":"https://ssp.kaigiroku.net/tenant/kamikawa/SpMinuteView.html?tenant_id=73&council_id=95&schedule_id=5","sourceTitle":"神川町議会 ３月18日本会議録 議案第29号の質疑"},{"date":"2026-03-18","stage":"体育館の工事請負契約議案を可決","actor":"神川町議会","detail":"体育館空調設備及び非常用発電機設置工事の請負契約議案を、異議なしで原案可決した。","url":"https://ssp.kaigiroku.net/tenant/kamikawa/SpMinuteView.html?tenant_id=73&council_id=95&schedule_id=5","sourceTitle":"神川町議会 ３月18日本会議録 議案第29号の採決","billNumber":"議案第29号"},{"date":"2026-06-04","actor":"柴崎愛子","stage":"活動場所の気温を測り、柔剣道場の空調を求める","detail":"柴崎議員は、複数の練習会場で温度を測ったと報告した。６月１日は外気温33度、柔剣道場２階の卓球部会場35度、体育館のバスケットボール部会場26度弱だったと示し、柔剣道場の空調を早急に整備するよう求めた。","url":"https://ssp.kaigiroku.net/tenant/kamikawa/SpMinuteView.html?tenant_id=73&council_id=96&schedule_id=2","sourceTitle":"神川町議会 ６月４日の本会議録 34頁・一般質問"},{"date":"2026-06-04","actor":"福嶋慶治 教育長","stage":"答弁","detail":"柔剣道場の老朽化や工事の費用を挙げ、空調を設置中の体育館や空き教室を活動に使う方法を研究すると答えた。早期の対策を求める再質問には、既存施設でできることを学校と相談する考えを示した。","url":"https://ssp.kaigiroku.net/tenant/kamikawa/SpMinuteView.html?tenant_id=73&council_id=96&schedule_id=2","sourceTitle":"神川町議会 ６月４日の本会議録 35・36頁・答弁"},{"date":"2026-09","actor":"柴崎愛子","stage":"現地見学を踏まえた次会期の質問通告","detail":"夏休みに部活動を見学し、早朝から練習する部の実情を記載。6月の質問を明示して、屋外の陸上部・野球部へのミスト扇風機導入を取り上げた。","url":"https://www.town.kamikawa.saitama.jp/material/files/group/18/ippannsitsumonn202609.pdf#page=2","sourceTitle":"神川町議会「令和8年第4回定例会・予定されている一般質問」"}],"note":"体育館工事の入札・契約議案、柔剣道場と校庭への暑さ対策を資料で確認しました。温度の計測は６月会議録にある議員の報告です。９月の通告に対する答弁、設備の完成・購入は確認中です。"}
]);
